CREATE OR REPLACE FUNCTION public.update_study_streak(user_uuid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  today date := current_date;
  last_date date;
  cur_streak integer;
  best_streak integer;
BEGIN
  SELECT last_study_date, study_streak, longest_streak INTO last_date, cur_streak, best_streak FROM profiles WHERE id = user_uuid;
  IF last_date = today THEN RETURN; ELSIF last_date = today - interval '1 day' THEN cur_streak := cur_streak + 1; ELSE cur_streak := 1; END IF;
  best_streak := GREATEST(best_streak, cur_streak);
  UPDATE profiles SET study_streak = cur_streak, longest_streak = best_streak, last_study_date = today WHERE id = user_uuid;
END;
$function$
